import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 인사발령 처리 완료 상태는 '마감'으로 한다 (BEHAVIOR.md에서 미정, 개발 담당자 결정).
const DONE_STATUS = '마감';
// 가정: 발령공고 분류
const ANNOUNCE_CATEGORY = '인사발령';

type Q = { query: (sql: string, params: Record<string, unknown>) => Promise<any[]> };

function idOf(raw: unknown): string {
  if (typeof raw !== 'string' || !/^[0-9]+$/.test(raw)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '인사발령 ID가 올바르지 않습니다.');
  }
  return raw;
}

function checkBoardId(data: Record<string, unknown>): void {
  const v = data['boardId'];
  if (v === undefined || v === null || v === '') {
    return;
  }
  if (!Number.isFinite(Number(v))) {
    throw new ApiError(400, 'VALIDATION_FAILED', '게시판 값이 올바르지 않습니다.');
  }
}

// 발령공고 게시 + 신규 게시물 알림. 공고에는 공고 목적 항목(대상자명·구분·발령일자·부서·직위)만 넣는다.
async function postAnnouncement(db: Q, id: string, userId: string): Promise<number> {
  const posted = await db.query(
    `INSERT INTO board_post (author_id, post_type, category, title, content, visibility_scope, created_at, updated_at)
     SELECT CAST(:userId AS bigint), '공지', :category,
       '[인사발령] ' || e.name || ' ' || a.appointment_type,
       '대상자: ' || e.name || chr(10) || '발령 구분: ' || a.appointment_type || chr(10)
         || '발령일자: ' || to_char(a.appointment_date, 'YYYY-MM-DD') || chr(10)
         || '발령 부서: ' || d.name
         || coalesce(chr(10) || '직위: ' || a.position_after, ''),
       '전체', now(), now()
     FROM personnel_appointment a
     JOIN employee e ON e.employee_id = a.employee_id
     JOIN department d ON d.department_id = a.department_id
     WHERE a.personnel_appointment_id = CAST(:id AS bigint)
     RETURNING board_post_id AS "boardPostId"`,
    { userId, category: ANNOUNCE_CATEGORY, id },
  );
  if (posted.length === 0) {
    throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령을 찾을 수 없습니다.');
  }
  const postId = Number(posted[0]['boardPostId']);
  await db.query(
    `INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at)
     SELECT e.employee_id, '포털', '신규 게시물: 인사발령 공고', '인사발령 공고가 게시되었습니다.', '안읽음',
       'NEW_POST', 'BOARD_POST', CAST(:postId AS bigint), now(), now()
     FROM employee e
     WHERE e.employment_status = '재직자'
     RETURNING notification_id AS "notificationId"`,
    { postId },
  );
  return postId;
}

@Controller('api/v1')
export class FnSfr01303Controller {
  @Post('/personnel-appointments/:personnelAppointmentId/process')
  @HttpCode(200)
  async processPersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const userId = user.id;
    if (!userId) {
      throw new ApiError(401, 'UNAUTHORIZED', '인증이 필요합니다.');
    }
    const id = idOf(req.params['personnelAppointmentId']);
    const data = checks.inputOf(req.body);
    checkBoardId(data);

    // 1단계: 처리 결과 확정 (공고 게시가 실패해도 유지한다)
    await transaction(async (db) => {
      const found = await db.query(
        `SELECT status FROM personnel_appointment WHERE personnel_appointment_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '처리할 인사발령을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '승인') {
        throw new ApiError(409, 'PERSONNEL_APPOINTMENT_STATUS_MISMATCH', '승인 상태의 인사발령만 처리할 수 있습니다.');
      }
      const changed = await db.execute(
        `UPDATE personnel_appointment
         SET status = :done, processed_by = CAST(:userId AS bigint), processed_at = now(), updated_at = now()
         WHERE personnel_appointment_id = CAST(:id AS bigint) AND status = '승인'`,
        { done: DONE_STATUS, userId, id },
      );
      if (changed === 0) {
        throw new ApiError(409, 'PERSONNEL_APPOINTMENT_STATUS_MISMATCH', '승인 상태의 인사발령만 처리할 수 있습니다.');
      }
      // 발령 후 부서를 임직원 정보에 반영
      await db.execute(
        `UPDATE employee
         SET department_id = a.department_id, updated_at = now()
         FROM personnel_appointment a
         WHERE a.personnel_appointment_id = CAST(:id AS bigint) AND employee.employee_id = a.employee_id`,
        { id },
      );
      await db.execute(
        `INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, change_reason, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), 'personnel_appointment', CAST(:id AS bigint), '발령 처리', now(), :content, NULL, now(), now())`,
        { userId, id, content: '상태 승인 -> ' + DONE_STATUS + ', 발령 내용 반영' },
      );
    });

    // 2단계: 발령공고 게시 (실패 시 502, 1단계 결과는 유지)
    // 가정: 처리 결과를 유지해야 하므로 공고 게시는 별도 트랜잭션으로 한다.
    try {
      const boardPostId = await transaction(async (db) => postAnnouncement(db, id, userId));
      return { personnelAppointmentId: Number(id), status: DONE_STATUS, boardPostId };
    } catch (e) {
      if (e instanceof ApiError) {
        throw e;
      }
      throw new ApiError(502, 'ANNOUNCEMENT_POST_FAILED', '발령 처리는 완료했지만 발령공고 게시에 실패했습니다. 다시 게시해 주세요.');
    }
  }

  @Post('/personnel-appointments/:personnelAppointmentId/repost-announcement')
  @HttpCode(200)
  async repostAppointmentAnnouncement(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const userId = user.id;
    if (!userId) {
      throw new ApiError(401, 'UNAUTHORIZED', '인증이 필요합니다.');
    }
    const id = idOf(req.params['personnelAppointmentId']);
    const data = checks.inputOf(req.body);
    checkBoardId(data);
    try {
      return await transaction(async (db) => {
        const found = await db.query(
          `SELECT status FROM personnel_appointment WHERE personnel_appointment_id = CAST(:id AS bigint)`,
          { id },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령을 찾을 수 없습니다.');
        }
        // 가정: 처리 완료된 발령만 재게시할 수 있다.
        if (found[0]['status'] !== DONE_STATUS) {
          throw new ApiError(409, 'INVALID_STATE', '처리가 완료된 인사발령만 공고를 다시 게시할 수 있습니다.');
        }
        const boardPostId = await postAnnouncement(db, id, userId);
        return { boardPostId };
      });
    } catch (e) {
      if (e instanceof ApiError) {
        throw e;
      }
      throw new ApiError(502, 'ANNOUNCEMENT_POST_FAILED', '발령공고 게시에 실패했습니다.');
    }
  }
}

