import { useState } from 'react';
import { ApiFail, Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, NumberInput, RefName, call } from '../kit';
import type { PageProps, Row } from '../kit';

type Mode = { kind: 'process' | 'repost'; id: number | string } | null;

export default function FnSfr01303Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [mode, setMode] = useState<Mode>(null);
  const [id, setId] = useState<number | string>('');
  const [boardId, setBoardId] = useState<number | string>('');

  function open(kind: 'process' | 'repost', targetId: number | string) {
    setId(targetId);
    setBoardId('');
    setMode({ kind, id: targetId });
  }

  function remember(row: Row) {
    setRows((prev) => [row, ...prev.filter((r) => r.id !== row.id)]);
  }

  async function run() {
    if (!mode) {
      return;
    }
    if (id === '') {
      throw new Error('인사발령을 선택해 주세요.');
    }
    const body: Row = boardId === '' ? {} : { boardId };
    const path = '/personnel-appointments/' + id + (mode.kind === 'process' ? '/process' : '/repost-announcement');
    try {
      const res = await call('POST', path, role, body);
      if (mode.kind === 'process') {
        remember({ id, status: res.status, boardPostId: res.boardPostId });
        notify('인사발령을 처리하고 발령공고를 게시했습니다.');
      } else {
        remember({ id, status: '마감', boardPostId: res.boardPostId });
        notify('발령공고를 다시 게시했습니다.');
      }
      setMode(null);
    } catch (e) {
      if (mode.kind === 'process' && e instanceof ApiFail && e.code === 'ANNOUNCEMENT_POST_FAILED') {
        remember({ id, status: '마감', boardPostId: '' });
      }
      throw e;
    }
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>인사발령 처리</h2>
        <Band total={rows.length}>
          <button onClick={() => open('process', '')}>인사발령 처리</button>
          <button className="ghost" onClick={() => open('repost', '')}>발령공고 재게시</button>
        </Band>
        <DataTable
          rows={rows}
          empty="아직 처리한 내역이 없습니다. 인사발령 처리 버튼으로 승인된 발령을 처리해 주세요."
          columns={[
            { key: 'id', label: '인사발령', render: (r) => <RefName table="personnel_appointment" role={role} value={r.id} /> },
            { key: 'status', label: '발령 상태', render: (r) => <Badge value={r.status} /> },
            { key: 'boardPostId', label: '발령공고', render: (r) => (r.boardPostId ? '게시됨' : '게시 안 됨') },
            {
              key: 'action',
              label: '처리',
              render: (r) => (r.boardPostId ? null : (
                <button className="ghost" onClick={() => open('repost', r.id as number | string)}>재게시</button>
              )),
            },
          ]}
        />
      </section>
      {mode && (
        <Drawer title={mode.kind === 'process' ? '인사발령 처리' : '발령공고 재게시'} onClose={() => setMode(null)}>
          <Form
            onSubmit={run}
            submit={mode.kind === 'process' ? '처리' : '재게시'}
            note={mode.kind === 'process' ? '처리하면 발령 내용이 반영되고 발령공고가 게시됩니다. 되돌릴 수 없습니다.' : undefined}
          >
            <Field label="인사발령" required wide>
              <LookupSelect table="personnel_appointment" role={role} value={id} onChange={setId} />
            </Field>
            <Field label="공고 게시 게시판" wide>
              <NumberInput value={boardId} onChange={setBoardId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
